#!/usr/bin/env bash
#
# Benchmark script for entities.mv_finra_brokerage_firm_targeting MV.
#
# Generated by validator stage of the /scope directive
#   Desktop/hq/directives/2026-05-02-dex-finra-brokerage-firm-mv.md
#
# Canonical invocation (from anywhere):
#
#   doppler run --project data-engine-x --config prd -- bash -c \
#     'apps/data-engine-x/scripts/benchmarks/dex-finra-brokerage-firm-mv.sh'
#
# Or with --apply-migration to run the new migration first:
#
#   doppler run --project data-engine-x --config prd -- bash -c \
#     'apps/data-engine-x/scripts/benchmarks/dex-finra-brokerage-firm-mv.sh \
#        --apply-migration apps/data-engine-x/supabase/migrations/20260503110000_mv_finra_brokerage_firm_targeting.sql \
#        --with-refresh'
#
# Reads DEX_DB_URL_DIRECT from env (must be session-mode, not pgbouncer).
# Read-only by default. --apply-migration applies the migration first.
# --with-refresh runs REFRESH MATERIALIZED VIEW CONCURRENTLY and times it
# (constraint C8). Default skips refresh so the script stays fast.
#
# Exit code 0 on all-pass, 1 otherwise.

set -euo pipefail

# --------------------------------------------------------------------------- #
# Args
# --------------------------------------------------------------------------- #

APPLY_MIGRATION=""
WITH_REFRESH=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    --apply-migration)
      APPLY_MIGRATION="$2"
      shift 2
      ;;
    --with-refresh)
      WITH_REFRESH=1
      shift
      ;;
    *)
      echo "ERROR: unknown arg: $1" >&2
      echo "Usage: $0 [--apply-migration <path>] [--with-refresh]" >&2
      exit 2
      ;;
  esac
done

# --------------------------------------------------------------------------- #
# Env
# --------------------------------------------------------------------------- #

if [[ -z "${DEX_DB_URL_DIRECT:-}" ]]; then
  echo "ERROR: DEX_DB_URL_DIRECT not set." >&2
  echo "Run via: doppler run --project data-engine-x --config prd -- bash -c '<cmd>'" >&2
  echo "(NOT: doppler run -- ...; the inner shell expansion gotcha — see CLAUDE.md.)" >&2
  exit 2
fi

# --------------------------------------------------------------------------- #
# Pinned values (from validator notes)
# --------------------------------------------------------------------------- #

MV_SCHEMA="entities"
MV_NAME="mv_finra_brokerage_firm_targeting"
SOURCE_TABLE="entities.source_finra_brokercheck_firms"
PINNED_MIGRATION_PATH="apps/data-engine-x/supabase/migrations/20260503110000_mv_finra_brokerage_firm_targeting.sql"
PINNED_CRON_JOBNAME="refresh_mv_finra_brokerage_firm_targeting_weekly"
PINNED_CRON_SCHEDULE="0 6 * * 1"
SOURCE_BAND_LOW=80000
SOURCE_BAND_HIGH=95000
REFRESH_MAX_SECONDS=180

# --------------------------------------------------------------------------- #
# Helpers
# --------------------------------------------------------------------------- #

PASS_COUNT=0
FAIL_COUNT=0

# psql wrapper — tuple-only, single-column, suppress \timing noise
pq() {
  psql "$DEX_DB_URL_DIRECT" -tAX -v ON_ERROR_STOP=1 -c "$1"
}

# pq_row: returns the single row from a query (used for multi-col output)
pq_row() {
  psql "$DEX_DB_URL_DIRECT" -tAXF $'\t' -v ON_ERROR_STOP=1 -c "$1"
}

# check: takes id, description, condition (already-evaluated PASS/FAIL string)
report() {
  local status="$1"; local id="$2"; local detail="$3"
  printf "%s  %-4s %s\n" "$status" "$id" "$detail"
  if [[ "$status" == "PASS" ]]; then
    PASS_COUNT=$((PASS_COUNT + 1))
  else
    FAIL_COUNT=$((FAIL_COUNT + 1))
  fi
}

# Convenience: run a query that should return a single value, compare to expected
# Usage: assert_eq <id> <description> <sql> <expected>
assert_eq() {
  local id="$1"; local desc="$2"; local sql="$3"; local expected="$4"
  local got
  if ! got="$(pq "$sql" 2>&1)"; then
    report "FAIL" "$id" "$desc — query error: $got"
    return
  fi
  if [[ "$got" == "$expected" ]]; then
    report "PASS" "$id" "$desc (got=$got)"
  else
    report "FAIL" "$id" "$desc (got=$got expected=$expected)"
  fi
}

# --------------------------------------------------------------------------- #
# Optional: apply migration
# --------------------------------------------------------------------------- #

if [[ -n "$APPLY_MIGRATION" ]]; then
  if [[ ! -f "$APPLY_MIGRATION" ]]; then
    echo "ERROR: --apply-migration: file not found: $APPLY_MIGRATION" >&2
    exit 2
  fi
  echo "Applying migration: $APPLY_MIGRATION"
  if psql "$DEX_DB_URL_DIRECT" -v ON_ERROR_STOP=1 -f "$APPLY_MIGRATION"; then
    echo "applied"
  else
    echo "failed"
    exit 1
  fi
fi

# --------------------------------------------------------------------------- #
# Find the migration file (for grep-based checks).
# Looks first at the pinned absolute path under any plausible repo root,
# then falls back to a glob search if not found there.
# --------------------------------------------------------------------------- #

MIGRATION_PATH=""
for candidate in \
  "/Users/benjamincrane/hq-all/$PINNED_MIGRATION_PATH" \
  "$PWD/$PINNED_MIGRATION_PATH" \
  "$PINNED_MIGRATION_PATH"; do
  if [[ -f "$candidate" ]]; then
    MIGRATION_PATH="$candidate"
    break
  fi
done

if [[ -z "$MIGRATION_PATH" ]]; then
  # vacuous-pass mode: file does not exist yet (validator baseline run)
  MIGRATION_PATH="(absent)"
fi

# --------------------------------------------------------------------------- #
# Constraint checks
# --------------------------------------------------------------------------- #

# C0 — source row count within sanity band (validator-added)
SOURCE_N="$(pq "SELECT COUNT(*) FROM $SOURCE_TABLE;")"
if [[ "$SOURCE_N" -ge "$SOURCE_BAND_LOW" && "$SOURCE_N" -le "$SOURCE_BAND_HIGH" ]]; then
  report "PASS" "C0" "source row count = $SOURCE_N (within sanity band $SOURCE_BAND_LOW-$SOURCE_BAND_HIGH)"
else
  report "FAIL" "C0" "source row count = $SOURCE_N (outside sanity band $SOURCE_BAND_LOW-$SOURCE_BAND_HIGH)"
fi

# Determine MV existence first — many subsequent checks key off this.
MV_EXISTS="$(pq "SELECT EXISTS(SELECT 1 FROM pg_matviews WHERE schemaname='$MV_SCHEMA' AND matviewname='$MV_NAME');")"

# C1 — MV exists
if [[ "$MV_EXISTS" == "t" ]]; then
  report "PASS" "C1" "$MV_SCHEMA.$MV_NAME exists"
else
  report "FAIL" "C1" "MV does not exist yet"
fi

# C2 — required columns present
REQUIRED_COLS=(
  crd_number firm_name firm_other_names
  bc_scope ia_scope finra_registered firm_status firm_status_date
  firm_size firm_type regulator district_name finra_last_approval_date
  formed_date formed_state firm_age_years
  ia_sec_number ia_sec_number_type bd_sec_number
  branches_count registered_rep_count disclosure_count
  regulatory_event_count civil_event_count arbitration_count
  bd_disclosure_flag ia_disclosure_flag
  approved_finra_registration_count approved_sec_registration_count
  approved_sro_registration_count approved_state_registration_count
  office_street1 office_street2 office_city office_state office_country office_postal_code
  mailing_street1 mailing_street2 mailing_city mailing_state mailing_country mailing_postal_code
  business_phone_number
  bc_active ia_active is_finra_registered is_dual_registered
  has_any_disclosure has_bd_disclosure has_ia_disclosure
  has_office_addr has_mailing_addr has_phone
  firm_size_band disclosure_band branches_band firm_age_band
)
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C2" "MV does not exist; cannot inspect columns"
else
  # information_schema.columns excludes materialized views — query pg_attribute instead.
  MV_COLS="$(pq "SELECT string_agg(a.attname, ',') FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.relkind = 'm' AND n.nspname = '$MV_SCHEMA' AND c.relname = '$MV_NAME' AND a.attnum > 0 AND NOT a.attisdropped;")"
  MISSING=()
  for col in "${REQUIRED_COLS[@]}"; do
    if [[ ",$MV_COLS," != *",$col,"* ]]; then
      MISSING+=("$col")
    fi
  done
  if [[ ${#MISSING[@]} -eq 0 ]]; then
    report "PASS" "C2" "all ${#REQUIRED_COLS[@]} required columns present"
  else
    report "FAIL" "C2" "missing columns: ${MISSING[*]}"
  fi
fi

# C3 — row-count parity (mv_n = source_n)
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C3" "row-count parity not yet meaningful (mv missing)"
else
  MV_N="$(pq "SELECT COUNT(*) FROM $MV_SCHEMA.$MV_NAME;")"
  if [[ "$MV_N" == "$SOURCE_N" ]]; then
    report "PASS" "C3" "mv_n=$MV_N == source_n=$SOURCE_N"
  else
    report "FAIL" "C3" "mv_n=$MV_N != source_n=$SOURCE_N"
  fi
fi

# C4 — PK uniqueness on crd_number
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C4" "PK uniqueness not yet meaningful (mv missing)"
else
  DUPS="$(pq "SELECT COUNT(*) FROM (SELECT crd_number FROM $MV_SCHEMA.$MV_NAME GROUP BY 1 HAVING COUNT(*) > 1) d;")"
  if [[ "$DUPS" == "0" ]]; then
    report "PASS" "C4" "no crd_number duplicates"
  else
    report "FAIL" "C4" "$DUPS crd_number values appear >1 time"
  fi
fi

# C5a — branch-count parity
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C5a" "branch-count parity not yet meaningful (mv missing)"
else
  MISMATCH="$(pq "SELECT COUNT(*) FROM $MV_SCHEMA.$MV_NAME m JOIN $SOURCE_TABLE s USING (crd_number) WHERE m.branches_count IS DISTINCT FROM s.branches_count;")"
  if [[ "$MISMATCH" == "0" ]]; then
    report "PASS" "C5a" "branches_count == source on every row"
  else
    report "FAIL" "C5a" "$MISMATCH rows where branches_count diverges from source"
  fi
fi

# C5b — disclosure-count formula
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C5b" "disclosure-count formula not yet meaningful (mv missing)"
else
  MISMATCH="$(pq "SELECT COUNT(*) FROM $MV_SCHEMA.$MV_NAME m JOIN $SOURCE_TABLE s USING (crd_number) WHERE m.disclosure_count IS DISTINCT FROM (COALESCE(s.regulatory_event_count, 0) + COALESCE(s.civil_event_count, 0) + COALESCE(s.arbitration_count, 0));")"
  if [[ "$MISMATCH" == "0" ]]; then
    report "PASS" "C5b" "disclosure_count formula matches on every row"
  else
    report "FAIL" "C5b" "$MISMATCH rows where disclosure_count != reg+civil+arb"
  fi
fi

# C5c — registered_rep_count is uniformly NULL (placeholder)
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C5c" "registered_rep_count placeholder not yet meaningful (mv missing)"
else
  NON_NULL="$(pq "SELECT COUNT(*) FROM $MV_SCHEMA.$MV_NAME WHERE registered_rep_count IS NOT NULL;")"
  if [[ "$NON_NULL" == "0" ]]; then
    report "PASS" "C5c" "registered_rep_count uniformly NULL (placeholder)"
  else
    report "FAIL" "C5c" "registered_rep_count has $NON_NULL non-null rows; placeholder expects all NULL"
  fi
fi

# C6 — no http/pg_net/fetch in the migration file
if [[ "$MIGRATION_PATH" == "(absent)" ]]; then
  report "PASS" "C6" "migration file absent — vacuous pass (no banned patterns to find)"
else
  if grep -qEn "http://|https://|pg_net\.|http\.|requests\.|urllib|httpx|fetch\(" "$MIGRATION_PATH"; then
    HITS="$(grep -cEn "http://|https://|pg_net\.|http\.|requests\.|urllib|httpx|fetch\(" "$MIGRATION_PATH")"
    report "FAIL" "C6" "migration contains $HITS banned http/pg_net/fetch lines"
  else
    report "PASS" "C6" "migration has no http/pg_net/fetch lines"
  fi
fi

# C7 — pg_cron job registered
JOB_COUNT="$(pq "SELECT COUNT(*) FROM cron.job WHERE jobname = '$PINNED_CRON_JOBNAME' AND schedule = '$PINNED_CRON_SCHEDULE' AND command ILIKE '%REFRESH MATERIALIZED VIEW CONCURRENTLY $MV_SCHEMA.$MV_NAME%';")"
if [[ "$JOB_COUNT" == "1" ]]; then
  report "PASS" "C7" "cron job '$PINNED_CRON_JOBNAME' registered with schedule '$PINNED_CRON_SCHEDULE'"
else
  report "FAIL" "C7" "no pg_cron job registered for this MV (got $JOB_COUNT matching rows)"
fi

# C8 (opt-in) — refresh time
if [[ "$WITH_REFRESH" -eq 1 ]]; then
  if [[ "$MV_EXISTS" != "t" ]]; then
    report "FAIL" "C8" "cannot refresh — MV does not exist"
  else
    START_TS="$(date +%s)"
    if psql "$DEX_DB_URL_DIRECT" -v ON_ERROR_STOP=1 -c "REFRESH MATERIALIZED VIEW CONCURRENTLY $MV_SCHEMA.$MV_NAME;" >/dev/null 2>&1; then
      END_TS="$(date +%s)"
      ELAPSED=$((END_TS - START_TS))
      if [[ "$ELAPSED" -le "$REFRESH_MAX_SECONDS" ]]; then
        report "PASS" "C8" "refresh completed in ${ELAPSED}s (bound: ${REFRESH_MAX_SECONDS}s)"
      else
        report "FAIL" "C8" "refresh took ${ELAPSED}s (bound: ${REFRESH_MAX_SECONDS}s)"
      fi
    else
      report "FAIL" "C8" "REFRESH MATERIALIZED VIEW CONCURRENTLY raised an error"
    fi
  fi
fi

# C9 — sanity bound on row count
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C9" "row-count sanity band check requires MV to exist"
else
  MV_N="$(pq "SELECT COUNT(*) FROM $MV_SCHEMA.$MV_NAME;")"
  if [[ "$MV_N" -ge "$SOURCE_BAND_LOW" && "$MV_N" -le "$SOURCE_BAND_HIGH" ]]; then
    report "PASS" "C9" "mv_n=$MV_N within sanity band $SOURCE_BAND_LOW-$SOURCE_BAND_HIGH"
  else
    report "FAIL" "C9" "mv_n=$MV_N outside sanity band $SOURCE_BAND_LOW-$SOURCE_BAND_HIGH"
  fi
fi

# C10 — migration is forward-only and additive
if [[ "$MIGRATION_PATH" == "(absent)" ]]; then
  report "PASS" "C10" "pinned migration filename absent (so grep is vacuously clean)"
else
  if grep -qiE "drop[[:space:]]+|alter[[:space:]]+(table|matview|materialized)|truncate" "$MIGRATION_PATH"; then
    HITS="$(grep -ciE "drop[[:space:]]+|alter[[:space:]]+(table|matview|materialized)|truncate" "$MIGRATION_PATH")"
    report "FAIL" "C10" "migration contains $HITS forbidden DROP/ALTER/TRUNCATE statements"
  else
    report "PASS" "C10" "migration is forward-only and additive (no DROP/ALTER/TRUNCATE)"
  fi
fi

# C11 — smoke query
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C11" "smoke query cannot run (mv missing)"
else
  SMOKE="$(pq "SELECT COUNT(*) FROM (SELECT crd_number, firm_name FROM $MV_SCHEMA.$MV_NAME WHERE bc_active AND ia_active AND has_office_addr ORDER BY branches_count DESC NULLS LAST LIMIT 25) q WHERE firm_name IS NOT NULL;")"
  if [[ "$SMOKE" -ge "1" && "$SMOKE" -le "25" ]]; then
    report "PASS" "C11" "smoke query returned $SMOKE rows (all with firm_name non-null)"
  else
    report "FAIL" "C11" "smoke query returned $SMOKE rows (expected 1..25 with firm_name set)"
  fi
fi

# C12 — indexes present
if [[ "$MV_EXISTS" != "t" ]]; then
  report "FAIL" "C12" "index list empty (mv missing)"
else
  IDX_COUNT="$(pq "SELECT COUNT(*) FROM pg_indexes WHERE schemaname='$MV_SCHEMA' AND tablename='$MV_NAME';")"
  UNIQ_CRD="$(pq "SELECT COUNT(*) FROM pg_indexes WHERE schemaname='$MV_SCHEMA' AND tablename='$MV_NAME' AND indexdef ILIKE 'CREATE UNIQUE INDEX%(crd_number)%';")"
  if [[ "$IDX_COUNT" -ge "13" && "$UNIQ_CRD" -ge "1" ]]; then
    report "PASS" "C12" "$IDX_COUNT indexes present (>=13 required), unique on crd_number present"
  else
    report "FAIL" "C12" "indexes=$IDX_COUNT (need >=13), unique-on-crd=$UNIQ_CRD (need >=1)"
  fi
fi

# --------------------------------------------------------------------------- #
# Summary
# --------------------------------------------------------------------------- #

TOTAL=$((PASS_COUNT + FAIL_COUNT))
echo "RESULT: ${PASS_COUNT}/${TOTAL}"

if [[ "$FAIL_COUNT" -eq 0 ]]; then
  exit 0
else
  exit 1
fi
